#!/usr/bin/env bun
import { $ } from "bun";
import { mkdir } from "node:fs/promises";

const OUT =
  "/Users/dhruv2mars/dev/github/portfolio/gauntlet/pieces/projects-list/r1";
await mkdir(OUT, { recursive: true });

async function ab(...args: string[]) {
  const r = await $`agent-browser ${args}`.nothrow();
  const out = (r.stdout.toString() + r.stderr.toString()).trim();
  console.log(out.slice(0, 800));
  return { code: r.exitCode, out };
}

await ab("close");
await ab("set", "viewport", "1440", "900");
await ab("open", "http://localhost:3000/projects");
await ab("wait", "2000");
await ab(
  "eval",
  `(() => {
  document.documentElement.classList.add('dark');
  document.documentElement.classList.remove('light');
  return JSON.stringify({
    h1: document.querySelector('h1')?.textContent,
    rows: document.querySelectorAll('.project-row').length,
    accent: getComputedStyle(document.documentElement).getPropertyValue('--color-accent').trim(),
  });
})()`,
);
await ab("wait", "400");
await ab("screenshot", `${OUT}/projects-desktop.png`);

await ab("set", "viewport", "390", "844");
await ab("wait", "800");
await ab(
  "eval",
  `(() => {
  document.documentElement.classList.add('dark');
  document.documentElement.classList.remove('light');
  return JSON.stringify({ w: innerWidth, rows: document.querySelectorAll('.project-row').length });
})()`,
);
await ab("wait", "400");
await ab("screenshot", `${OUT}/projects-mobile.png`);

console.log("ALL DONE");

