import { chromium } from "playwright";
import { mkdir } from "node:fs/promises";

const OUT =
  "/Users/dhruv2mars/dev/github/portfolio/gauntlet/pieces/projects-list/r1";
await mkdir(OUT, { recursive: true });

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage();

async function dark() {
  await page.evaluate(() => {
    localStorage.setItem("portfolio-theme", "dark");
    document.documentElement.classList.add("dark");
    document.documentElement.classList.remove("light");
  });
}

await page.setViewportSize({ width: 1440, height: 900 });
await page.goto("http://127.0.0.1:3000/projects", {
  waitUntil: "networkidle",
});
await dark();
await page.waitForTimeout(1200);
const meta = await page.evaluate(() => ({
  h1: document.querySelector("h1")?.textContent,
  rows: document.querySelectorAll(".project-row").length,
  accent: getComputedStyle(document.documentElement)
    .getPropertyValue("--color-accent")
    .trim(),
}));
console.log(JSON.stringify(meta));
await page.screenshot({
  path: `${OUT}/projects-desktop.png`,
  fullPage: false,
});

await page.setViewportSize({ width: 390, height: 844 });
await page.waitForTimeout(700);
await dark();
await page.evaluate(() => window.scrollTo(0, 0));
await page.screenshot({
  path: `${OUT}/projects-mobile.png`,
  fullPage: false,
});

// Home selected projects (compact)
await page.setViewportSize({ width: 1440, height: 900 });
await page.goto("http://127.0.0.1:3000/", { waitUntil: "networkidle" });
await dark();
await page.waitForTimeout(1000);
await page.evaluate(() => {
  document
    .querySelector("#home-projects-heading")
    ?.closest("section")
    ?.scrollIntoView({ block: "center" });
});
await page.waitForTimeout(500);
await page.screenshot({
  path: `${OUT}/home-selected-desktop.png`,
  fullPage: false,
});

await page.setViewportSize({ width: 390, height: 844 });
await page.waitForTimeout(600);
await page.evaluate(() => {
  document
    .querySelector("#home-projects-heading")
    ?.closest("section")
    ?.scrollIntoView({ block: "center" });
});
await page.waitForTimeout(400);
await page.screenshot({
  path: `${OUT}/home-selected-mobile.png`,
  fullPage: false,
});

await browser.close();
console.log("DONE");

