    radial-gradient(
      65% 45% at 100% 100%,
      color-mix(in srgb, var(--color-background-muted) 85%, transparent),
      transparent 55%
    ),
    /* Structural grid — visible field lines */
    linear-gradient(var(--grid-color) 1px, transparent 1px),
    linear-gradient(90deg, var(--grid-color) 1px, transparent 1px);
  background-size:
    auto,
    auto,
    auto,
    auto,
    48px 48px,
    48px 48px;
  background-position: center;
  transition: background-color var(--duration-theme) var(--ease-out-quad);
}

