import { ArrowUpRight } from "@/components/icons";
import type { Project } from "@/lib/projects";

type ProjectListProps = {
  projects: readonly Project[];
  headingId?: string;
  compact?: boolean;
};

/** Editorial outbound label — hostname + path, no protocol. */
function projectOutboundLabel(url: string): string {
  try {
    const parsed = new URL(url);
    const host = parsed.hostname.replace(/^www\./, "");
    const path = parsed.pathname.replace(/\/$/, "");
    if (!path || path === "/") return host;
    return `${host}${path}`;
  } catch {
    return url;
  }
}

export function ProjectList({
  projects,
  headingId,
  compact = false,
}: ProjectListProps) {
  return (
    <ul
      className={
        compact ? "project-list project-list--compact" : "project-list"
      }
      {...(headingId ? { "aria-labelledby": headingId } : {})}
    >
      {projects.map((project) => {
        const outbound = projectOutboundLabel(project.url);
        return (
          <li key={project.name} className="project-list__item">
            <a
              href={project.url}
              target="_blank"
              rel="noopener noreferrer"
              className="project-row"
            >
              <div className="project-row__main">
                <div className="project-row__headline">
                  <span className="project-row__name">{project.name}</span>
                  {project.year !== undefined ? (
                    <span className="project-row__year project-row__year--inline">
                      {project.year}
                    </span>
                  ) : null}
                </div>
                <p className="project-row__desc">{project.description}</p>
              </div>
              <div className="project-row__meta">
                <span className="project-row__host" aria-hidden="true">
                  <span className="project-row__host-text">{outbound}</span>
                  <ArrowUpRight
                    size={compact ? 12 : 13}
                    weight="bold"
                    className="project-row__arrow"
                  />
                </span>
                {project.year !== undefined ? (
                  <span className="project-row__year project-row__year--rail">
                    {project.year}
                  </span>
                ) : null}
              </div>
            </a>
          </li>
        );
      })}
    </ul>
  );
}
