import { motion, useReducedMotion } from "motion/react";
import { duration, easeOutExpo } from "@/lib/motion";

/**
 * Quiet scroll reveal — one rise-and-fade as the section enters view.
 * Reduced motion: opacity only, shorter, no translate.
 */
export function Reveal({
  children,
  className,
}: {
  children: React.ReactNode;
  className?: string;
}) {
  const reduce = useReducedMotion();

  return (
    <motion.div
      className={className}
      initial={reduce ? { opacity: 0 } : { opacity: 0, y: 8 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: "-48px" }}
      transition={{
        duration: reduce ? 0.18 : duration.reveal,
        ease: easeOutExpo,
      }}
    >
      {children}
    </motion.div>
  );
}
